// Ek katmanın (Z-Anatomy) ana modele göre bölgeden bölgeye değişen kayması için düzeltme alanı.
// Z-Anatomy de BodyParts3D'den türediği için iki modelde aynı yapının yüzeyi bulunur (beyin çekirdekleri, göz, arterler, organlar).
// Bu yüzeyler 3 cm'lik yükseklik dilimlerinde en yakın nokta eşlemesiyle karşılaştırıldı (22.11.2026, 1317 eşleşme, kalan sapma 2 mm altı).
// Ölçülen kayma: baş bölgesinde ek katman yaklaşık 11 mm önde ve 6 mm aşağıda, gövdede 7 mm aşağıda ve 1-2 mm önde,
// bacakta diz altında yaklaşık 12 mm dışta ve 12 mm arkada, el ve el bileğinde 15-25 mm aşağıda.
// Tek bir sabit öteleme bu farkları gideremediği için her nokta, bu ölçümlerden üretilmiş 3 cm aralıklı bir ızgaradan
// (ters uzaklık ağırlıklı ortalama, ölçüm olmayan yerde gövdenin 7 mm'lik ortalama ötelemesi) üç doğrusal okunan ötelemeyle taşınır.
// Izgara: başlangıç (X0, Y0, Z0) metre, adım A metre, NX × NY × NZ hücre; her hücrede x, y, z ötelemesi, 0,5 mm biriminde işaretli bayt.
const A = 0.03, X0 = -0.36, Y0 = -0.03, Z0 = -0.21, NX = 25, NY = 63, NZ = 17, BIRIM = 0.0005;
const VERI = '';
let izgara = null;
function izgaraAl() {
  if (izgara) return izgara;
  const ham = atob(VERI); izgara = new Int8Array(ham.length);
  for (let i = 0; i < ham.length; i++) izgara[i] = ham.charCodeAt(i) << 24 >> 24;
  return izgara;
}
const sinirla = (v, n) => Math.max(0, Math.min(n - 1.000001, v));

// Konumun (metre) ötelemesini [dx, dy, dz] (metre) olarak çıkış dizisine yazar.
export function kayma(x, y, z, cikis) {
  const g = izgaraAl();
  const fx = sinirla((x - X0) / A, NX), fy = sinirla((y - Y0) / A, NY), fz = sinirla((z - Z0) / A, NZ);
  const i = Math.floor(fx), j = Math.floor(fy), k = Math.floor(fz), u = fx - i, v = fy - j, w = fz - k;
  cikis[0] = cikis[1] = cikis[2] = 0;
  for (let a = 0; a < 2; a++) for (let b = 0; b < 2; b++) for (let c = 0; c < 2; c++) {
    const agirlik = (a ? u : 1 - u) * (b ? v : 1 - v) * (c ? w : 1 - w);
    const o = (((i + a) * NY + (j + b)) * NZ + (k + c)) * 3;
    for (let q = 0; q < 3; q++) cikis[q] += agirlik * g[o + q] * BIRIM;
  }
  return cikis;
}

// Geometrinin bütün noktalarını düzeltme alanıyla taşır (geometri dünya koordinatında olmalı).
export function kaymaUygula(geometri) {
  const p = geometri.attributes.position, d = [0, 0, 0];
  for (let n = 0; n < p.count; n++) {
    kayma(p.getX(n), p.getY(n), p.getZ(n), d);
    p.setXYZ(n, p.getX(n) + d[0], p.getY(n) + d[1], p.getZ(n) + d[2]);
  }
  p.needsUpdate = true;
}
